// One Google Sheet holds a month of campaigns. Row 1 is the header (the Read sheet node turns it
// into the keys) and is frozen, so the languages are defined once for the whole sheet. Then one
// block per campaign, separated by a blank row:
//   field      | en | de | ...      header row (row 1): one column per language
//   <campaign> | <date>             title row
//   headline   | ...               one row per field
// Campaigns can use different fields. A campaign renders only the languages that have at least one
// cell filled in. Cells are kept as typed; the empty / "-" rules are applied when the jobs are built.
const url = $('Settings (sheet)').first().json.sheetUrl;
const spreadsheetId = url.match(/\/d\/([a-zA-Z0-9_-]+)/)?.[1];
if (!spreadsheetId) throw new Error('The sheetUrl in the Settings node is not a Google Sheets link.');

const rows = $input.all().map((i) => i.json);
const slug = (s) => String(s ?? '').trim().replace(/\s+/g, '-').toLowerCase();
const keys = [...new Set(rows.flatMap((r) => Object.keys(r)))].filter((k) => k !== 'row_number' && k.trim());
const fieldKey = keys[0];
if (String(fieldKey ?? '').trim().toLowerCase() !== 'field') throw new Error(`Cell A1 must be "field" (the header row holds "field" and the languages), found "${fieldKey ?? ''}".`);
const cols = []; // [language code, column key]
for (const key of keys.slice(1)) {
  const code = slug(key);
  if (cols.some(([l]) => l === code)) throw new Error(`The language "${code}" appears twice in the header row.`);
  cols.push([code, key]);
}
if (!cols.length) throw new Error('No languages in the header row.');

const val = (row, key) => String(row[key] ?? '').trim();
// The Read sheet node may drop blank rows, so a title row is also recognised by its date.
const DATE = /^\d{4}[-./]\d{1,2}[-./]\d{1,2}$|^\d{1,2}[-./]\d{1,2}[-./]\d{2,4}$/;
const looksLikeTitle = (row) => DATE.test(val(row, cols[0][1])) && cols.slice(1).every(([, key]) => val(row, key) === '');

const campaigns = [];
let cur = null;
let prev = null;
rows.forEach((row, i) => {
  const num = Number(row.row_number) || i + 2;
  const blank = !val(row, fieldKey) && cols.every(([, key]) => val(row, key) === '');
  if (blank || (prev !== null && num - prev > 1)) cur = null; // blank row (or a gap in row numbers) ends a block
  prev = num;
  if (blank) return;
  const at = `Row ${num}`;
  if (!cur || looksLikeTitle(row)) { // title row
    if (!val(row, fieldKey)) throw new Error(`${at}: expected the campaign name in column A.`);
    cur = { name: val(row, fieldKey), date: val(row, cols[0][1]), fields: {} };
    cur.label = cur.date ? `${cur.name} (${cur.date})` : cur.name;
    if (campaigns.some((c) => c.label === cur.label)) throw new Error(`${at}: the campaign "${cur.label}" appears twice.`);
    campaigns.push(cur);
    return;
  }
  const field = val(row, fieldKey).toLowerCase(); // field row
  if (!field) throw new Error(`${at}: a row under "${cur.name}" has values but no field name in column A.`);
  if (cur.fields[field]) throw new Error(`${at}: the field "${field}" appears twice under "${cur.name}".`);
  cur.fields[field] = Object.fromEntries(cols.map(([code, key]) => [code, val(row, key)]));
});
for (const c of campaigns) {
  if (!Object.keys(c.fields).length) throw new Error(`The campaign "${c.name}" has no field rows.`);
  c.languages = cols.map(([code]) => code).filter((code) => Object.values(c.fields).some((v) => v[code] !== ''));
}
if (!campaigns.length) throw new Error('No campaigns found in the sheet. Each block starts with the campaign name in column A and the date in column B, under the header row.');
return [{ json: { spreadsheetId, campaigns } }];

// The project comes from the Settings node. With no projectName, the default project is used.
const { projectName } = $('Settings (sheet)').first().json;
const projects = $('Get projects').first().json.projects;
const name = String(projectName ?? '').trim();
const project = name ? projects.find((p) => p.name === name) : projects.find((p) => p.default);
if (!project) {
  throw new Error(name
    ? `Project "${name}" is not in Creatives. Set projectName in the Settings node to one of: ${projects.map((p) => p.name).join(', ')}.`
    : 'No default project in Creatives. Set projectName in the Settings node.');
}
return [{ json: { Project: project.name } }];

// A campaign is one block of the sheet (see Parse sheet): rows are fields, columns are languages.
// The output is one payload for the Figma plugin, which builds a page with a frame per language and template/ratio.
// Text may mark emphasis with **double asterisks**; the plugin styles that part.
// A cell left empty is not sent, so the design keeps its default for that layer.
// A cell containing only "-" hides the layer (the renderer treats "" as hidden).
const form = $('Creative form').first().json;
const { spreadsheetId, campaigns } = $('Parse sheet').first().json;
const label = $('Choose campaign').first().json.Campaign;
const campaign = campaigns.find((c) => c.label === label);
if (!campaign) throw new Error(`Campaign "${label}" is no longer in the sheet.`);
const date = isoDate(campaign.date);
if (!date) throw new Error(`The campaign "${campaign.name}" needs a date in column B of its title row (for example 12.10.2026), found "${campaign.date ?? ''}".`);
const projects = $('Get projects').first().json.projects;
const projectName = $('Pick project').first().json.Project;
const projectId = projects.find((p) => p.name === projectName)?.id;
if (!projectId) throw new Error(`Project "${projectName}" is no longer in Creatives.`);
const picked = $('Choose creatives').first().json.Creatives;
const creatives = (Array.isArray(picked) ? picked : [picked]).map((v) => {
  const i = String(v).lastIndexOf('/');
  return { template: v.slice(0, i), ratio: v.slice(i + 1) };
});

// The date names the Drive folders in the export flow (year / month / campaign), so it must be readable.
// Day first for 12.10.2026 style dates; also accepts 2026-10-12 and a raw sheet serial number.
function isoDate(text) {
  const t = String(text ?? '').trim();
  let y, m, d;
  let hit;
  if ((hit = t.match(/^(\d{4})[-./](\d{1,2})[-./](\d{1,2})$/))) [y, m, d] = hit.slice(1).map(Number);
  else if ((hit = t.match(/^(\d{1,2})[-./](\d{1,2})[-./](\d{2,4})$/))) { [d, m, y] = hit.slice(1).map(Number); if (y < 100) y += 2000; }
  else if (/^\d{5}$/.test(t)) { const x = new Date(Date.UTC(1899, 11, 30) + Number(t) * 86400000); [y, m, d] = [x.getUTCFullYear(), x.getUTCMonth() + 1, x.getUTCDate()]; }
  if (!y || m < 1 || m > 12 || d < 1 || d > 31) return null;
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}
const slug = (s) => String(s ?? '').trim().replace(/\s+/g, '-').toLowerCase();
const wantLanguages = String(form.Languages ?? '').split(',').map(slug).filter(Boolean);
const languages = campaign.languages.filter((l) => !wantLanguages.length || wantLanguages.includes(l));
if (!languages.length) throw new Error(`None of the languages you entered are in "${campaign.name}". It has: ${campaign.languages.join(', ')}.`);

const jobs = [];
for (const language of languages) {
  const data = {};
  for (const [field, values] of Object.entries(campaign.fields)) {
    const value = String(values[language] ?? '').trim();
    if (value === '-') data[field] = '';
    else if (value !== '') data[field] = value;
  }
  for (const { template, ratio } of creatives) {
    jobs.push({
      template, ratio, language, data,
    });
  }
}
// Resolved like the renderer: a missing key keeps the design, "" hides the layer.
return [{ json: { campaign: campaign.name, date, jobs } }];

// Reads the page link from the form and the Drive root from the Settings node.
const form = $input.first().json;
const link = String(form['Figma page URL'] ?? '').trim();
const file = link.match(/figma\.com\/(?:design|file)\/([A-Za-z0-9]+)/);
if (!file) throw new Error('The Figma page URL is not a figma.com/design link.');
// Regex instead of new URL(): URL is not reliably available in the Code node sandbox.
const node = (link.match(/[?&]node-id=([^&#]+)/)?.[1] ?? '').replace(/%3A/i, ':').replace('-', ':');
if (!node) throw new Error('The link has no node-id. In Figma, right-click the campaign page in the Pages list and choose Copy link.');

const root = String(form.driveRootFolderUrl ?? '').trim();
const rootId = root.match(/folders\/([A-Za-z0-9_-]+)/)?.[1] ?? (/^[A-Za-z0-9_-]{15,}$/.test(root) ? root : null);
if (!rootId || root.includes('REPLACE_WITH')) throw new Error('Set the Drive root folder URL in the Settings node (a drive.google.com/drive/folders/… link).');

return [{ json: { fileKey: file[1], nodeId: node, rootId, scale: parseInt(form.Scale, 10) || 1 } }];

// The page name is "DD.MM.YYYY Campaign title" (the plugin names it so). Frames are "template/ratio/language".
// Hidden frames are skipped, so hide any you do not want exported.
const { fileKey, nodeId, rootId, scale } = $('Parse form').first().json;
const page = $input.first().json.nodes?.[nodeId]?.document;
if (!page) throw new Error('Figma did not return that page. Check the link and that the token can read the file.');
if (page.type !== 'CANVAS') throw new Error(`That link points to a ${page.type.toLowerCase()}, not a page. Right-click the campaign page in the Pages list and choose Copy link.`);

const head = page.name.match(/^(\d{2})\.(\d{2})\.(\d{4})\s+(.+)$/);
if (!head) throw new Error(`The page is named "${page.name}". It must start with the campaign date, like "12.10.2026 Autumn Sale".`);
const [, dd, mm, yyyy, title] = head;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
if (Number(mm) < 1 || Number(mm) > 12) throw new Error(`"${page.name}" has no valid month.`);

const NAME = /^([^/]+)\/([^/]+)\/([^/]+)$/;
const frames = [];
const walk = (n) => {
  for (const c of n.children ?? []) {
    if (c.visible === false) continue;
    if (c.type === 'SECTION') walk(c);
    else if (c.type === 'FRAME') {
      const m = c.name.match(NAME);
      if (m) frames.push({ id: c.id, template: m[1].trim(), ratio: m[2].trim(), language: m[3].trim() });
    }
  }
};
walk(page);
if (!frames.length) throw new Error(`No frames named template/ratio/language on "${page.name}".`);

// One template per campaign, so each format folder holds DDMM-CC-LANG.jpg once per language.
const seen = new Map();
for (const f of frames) {
  f.fileName = `${dd}${mm}-CC-${f.language.toUpperCase()}.jpg`;
  const slot = `${f.ratio}/${f.fileName}`;
  if (seen.has(slot)) throw new Error(`"${seen.get(slot)}" and "${f.template}/${f.ratio}/${f.language}" would both become ${slot}. A campaign page should use one template; hide or rename one.`);
  seen.set(slot, `${f.template}/${f.ratio}/${f.language}`);
}

return [{ json: {
  fileKey, rootId, scale, frames,
  year: yyyy, month: `${mm}. ${MONTHS[Number(mm) - 1]}`, campaign: `${dd}.${mm}.${yyyy} ${title.trim()}`,
  ratios: [...new Set(frames.map((f) => f.ratio))],
} }];

// Figma renders many frames per request; keep each URL short.
const p = $input.first().json;
const ids = p.frames.map((f) => f.id);
const out = [];
for (let i = 0; i < ids.length; i += 30) out.push({ json: { fileKey: p.fileKey, scale: p.scale, ids: ids.slice(i, i + 30).join(',') } });
return out;

const plan = $('Plan export').first().json;
const urls = {};
for (const item of $input.all()) Object.assign(urls, item.json.images ?? {});
const missing = plan.frames.filter((f) => !urls[f.id]);
if (missing.length) throw new Error(`Figma could not render: ${missing.map((f) => `${f.template}/${f.ratio}/${f.language}`).join(', ')}. Frames over about 32 megapixels fail at 2x; try 1x.`);
return [{ json: { ...plan, frames: plan.frames.map((f) => ({ ...f, url: urls[f.id] })) } }];

// One folder per format (the ratio part of the frame names), for example Desktop and Mobile.
const p = $('Image URLs').first().json;
const parentId = $('Ensure campaign').first().json.id;
return p.ratios.map((name) => ({ json: { name, parentId } }));

const p = $('Image URLs').first().json;
const folders = Object.fromEntries($('Ensure format').all().map((i) => [i.json.name, i.json.id]));
return p.frames.map((f) => ({ json: { fileName: f.fileName, folderId: folders[f.ratio], url: f.url } }));
